-- Modify "cases" table
ALTER TABLE "moderation"."cases" DROP CONSTRAINT "cases_action_target_check", ADD CONSTRAINT "cases_action_target_check" CHECK ((decision_action IS NULL) OR ((decision_action = 'HIDE'::text) AND (target_kind = ANY (ARRAY['COMMENT'::text, 'FORUM_ENTRY'::text, 'REVIEW'::text, 'CHAT_MESSAGE'::text]))) OR ((decision_action = ANY (ARRAY['WARN'::text, 'BAN'::text])) AND (target_kind = ANY (ARRAY['COMMENT'::text, 'FORUM_ENTRY'::text, 'BUYER'::text, 'REVIEW'::text, 'CHAT_MESSAGE'::text]))) OR ((decision_action = 'TAKEDOWN'::text) AND (target_kind = ANY (ARRAY['POST'::text, 'COMMENT'::text, 'FORUM_ENTRY'::text])))), DROP CONSTRAINT "cases_target_kind_check", ADD CONSTRAINT "cases_target_kind_check" CHECK (target_kind = ANY (ARRAY['POST'::text, 'COMMENT'::text, 'FORUM_ENTRY'::text, 'BUYER'::text, 'REVIEW'::text, 'CHAT_MESSAGE'::text])), ADD CONSTRAINT "cases_reverse_reason_check" CHECK ((reverse_reason IS NULL) OR ((char_length(reverse_reason) >= 1) AND (char_length(reverse_reason) <= 500) AND (reverse_reason !~ '^[\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000]|[\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000]$'::text))), ADD CONSTRAINT "cases_reversed_by_check" CHECK (reversed_by_admin_id > 0), ADD CONSTRAINT "cases_reversed_hide_check" CHECK ((reversed_at IS NULL) OR (decision_action = 'HIDE'::text)), ADD CONSTRAINT "cases_reversed_together_check" CHECK (((reversed_at IS NULL) AND (reversed_by_admin_id IS NULL) AND (reverse_reason IS NULL)) OR ((reversed_at IS NOT NULL) AND (reversed_by_admin_id IS NOT NULL) AND (reverse_reason IS NOT NULL) AND (closed_at IS NOT NULL) AND (reversed_at >= closed_at))), ADD COLUMN "reversed_at" timestamptz NULL, ADD COLUMN "reversed_by_admin_id" bigint NULL, ADD COLUMN "reverse_reason" text NULL;
